use std::collections::BTreeSet;
use super::statistical_causal_ml_support::{self,AnalysisQuestion3,QualifiedAnalysisResult1};
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.statistical-causal-ml-copilot-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct AnalysisCopilotRequest{pub analysis_request:AnalysisQuestion3,pub action_order:Vec<String>,pub action_budget:u64,pub dry_run:bool,pub signed_approval:bool,pub federation_approved:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct AnalysisCopilotReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub disposition:String,pub action_order:Vec<String>,pub admitted_action_order:Vec<String>,pub denied_action_order:Vec<String>,pub analysis_disposition:String,pub analysis_digest:ContentHash,pub copilot_digest:ContentHash,pub replay_identity:ContentHash,pub omissions:Vec<String>,pub uncertainty:Vec<String>,pub negative_evidence:Vec<String>,pub effect_receipts:Vec<String>,pub artifact:serde_json::Value,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum AnalysisCopilotError{#[error("invalid analysis copilot request: {0}")]Invalid(String),#[error("analysis qualification failed: {0}")]Analysis(String),#[error("analysis copilot artifact failed: {0}")]Artifact(String),#[error("invalid analysis copilot receipt: {0}")]Receipt(String)}
fn h(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn o(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}
impl AnalysisCopilotReceipt{pub fn validate(&self)->Result<(),AnalysisCopilotError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.action_order.is_empty()||![&self.analysis_digest,&self.copilot_digest,&self.replay_identity].into_iter().all(h){return Err(AnalysisCopilotError::Receipt("analysis copilot identity or digest is incomplete".into()));}for v in [&self.action_order,&self.admitted_action_order,&self.denied_action_order,&self.omissions,&self.uncertainty,&self.negative_evidence,&self.effect_receipts]{if !o(v){return Err(AnalysisCopilotError::Receipt("analysis copilot vectors are not canonical".into()));}}let ids=self.action_order.iter().cloned().collect::<BTreeSet<_>>();let p=self.admitted_action_order.iter().chain(&self.denied_action_order).cloned().collect::<BTreeSet<_>>();if ids!=p||self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.copilot_digest.as_str()){return Err(AnalysisCopilotError::Receipt("analysis copilot actions do not partition".into()));}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,scale:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["imaging core scientist","analysis operator","research program lead"],"behavior":format!("run approval-bounded analysis actions for {scale}"),"value":"turns qualified statistical evidence into a replayable copilot decision without hidden effects","input_schema":"AnalysisCopilotRequest1@1","output_schema":"AnalysisCopilotReceipt1@1","effects":["invoke:bounded-analysis-tool","block:unsafe-release"],"permissions":["invoke:declared-analysis-tool"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":PRECLINICAL_BOUNDARY})}
pub fn run(r:&AnalysisCopilotRequest,feature_id:&str,version:&str,_scale:&str,require_approval:bool,_federation:bool)->Result<AnalysisCopilotReceipt,AnalysisCopilotError>{if r.boundary!=PRECLINICAL_BOUNDARY||r.action_order.is_empty()||r.action_order!={let mut x=r.action_order.clone();x.sort();x.dedup();x}||r.action_budget==0||!r.analysis_request.raw_data_local||!r.analysis_request.federated_summary_only{return Err(AnalysisCopilotError::Invalid("analysis copilot request is invalid".into()))}let analysis=statistical_causal_ml_support::qualify(&r.analysis_request,feature_id,version).map_err(|e|AnalysisCopilotError::Analysis(e.to_string()))?;let mut omissions=analysis.omissions.clone();let approved=!require_approval||r.signed_approval;if !approved{omissions.push("copilot:approval-missing".into())}if r.dry_run{omissions.push("copilot:dry-run-no-effect".into())}if r.action_order.len()as u64>r.action_budget{omissions.push("copilot:action-budget-exceeded".into())}omissions.sort();omissions.dedup();let safe=analysis.disposition=="qualified"&&approved&&r.action_order.len()as u64<=r.action_budget;let disposition=if safe{"qualified"}else if analysis.disposition=="blocked"||!approved{"blocked"}else{"partial"};let admitted=if safe{r.action_order.clone()}else{Vec::new()};let denied=if safe{Vec::new()}else{r.action_order.clone()};let effects=if disposition=="blocked"{vec!["block:unsafe-release".into()]}else{vec![format!("invoke:bounded-analysis-tool:{}",analysis.analysis_digest)]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"request_id":r.analysis_request.request_id,"disposition":disposition,"action_order":r.action_order,"admitted_action_order":admitted,"denied_action_order":denied,"analysis_disposition":analysis.disposition,"analysis_digest":analysis.analysis_digest,"replay_identity":analysis.replay_identity,"omissions":omissions,"uncertainty":analysis.uncertainty,"negative_evidence":analysis.negative_evidence,"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|AnalysisCopilotError::Artifact(e.to_string()))?;let out=AnalysisCopilotReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),request_id:r.analysis_request.request_id.clone(),disposition:disposition.into(),action_order:r.action_order.clone(),admitted_action_order:admitted,denied_action_order:denied,analysis_disposition:analysis.disposition,analysis_digest:analysis.analysis_digest,copilot_digest:d.clone(),replay_identity:analysis.replay_identity,omissions:payload["omissions"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),uncertainty:analysis.uncertainty,negative_evidence:analysis.negative_evidence,effect_receipts:effects,artifact:json!({"content_type":CONTENT_TYPE,"content_hash":d,"boundary":PRECLINICAL_BOUNDARY}),raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};out.validate()?;Ok(out)}
